# Standalone Python 3, stdlib only, no imports, no I/O, deterministic, exact integer arithmetic.
# Entry point: verify(witness) -- raises on any failed check, returns True on PASS.

def small_factors(x, k):
    if x < 2:
        return False
    d = 2
    while d * d <= x:
        if x % d == 0:
            if d > k:
                return False
            while x % d == 0:
                x //= d
        d += 1
    if x > 1 and x > k:
        return False
    return True

def all_small_window(n, k):
    return all(small_factors(n + i, k) for i in range(k))

def verify(witness):
    B = witness['bound']
    if witness['k_values'] != [2, 3, 4]:
        raise ValueError('bad k_values')
    expected = {
        2: sorted(witness['exception_sets']['k2']),
        3: sorted(witness['exception_sets']['k3']),
        4: sorted(witness['exception_sets']['k4']),
    }
    for k in (2, 3, 4):
        found = []
        for n in range(2, B - k + 2):
            if all_small_window(n, k):
                if n == 2 or not all_small_window(n - 1, k):
                    found.append(n)
        if found != expected[k]:
            raise ValueError('mismatch k=%d found=%s expected=%s' % (k, found, expected[k]))
    return True

WITNESS = {
    'bound': 1000000,
    'k_values': [2, 3, 4],
    'exception_sets': {'k2': [2, 8], 'k3': [8, 24], 'k4': [24]},
}

verify(WITNESS)
